<div id="step-product" class="mb-3">
  <label><strong>**Step 1:** Choose a Data Product</strong></label>
  <select id="productFilter" class="form-select">
    <option value="">-- Select --</option>
    <option value="All">All</option>
    <option value="SST">SST</option>
    <option value="Ocean Color">Ocean Color</option>
    <option value="Wind">Wind</option>
    <option value="Salinity">Salinity</option>
    <option value="Sea Level & Geostrophic Currents">Sea Level & Geostrophic Currents</option>
  </select>
</div>

<!-- Step 2 -->
<div id="step-sensor" class="mb-3" style="display: none;">
  <label><strong>**Step 2:** What Type of Sensor?</strong></label>
  <select id="sensorTypeFilter" class="form-select">
    <option value="">-- Select --</option>
    <option value="All">All</option>
    <option value="Single">Single</option>
    <option value="Multi-Sensor">Multi-Sensor</option>
  </select>
</div>

<!-- Step 3 -->
<div id="step-region" class="mb-3" style="display: none;">
  <label><strong>**Step 3:** Select Region</strong></label>
  <select id="regionFilter" class="form-select">
    <option value="">-- Select --</option>
    <option value="All">All</option>
    <option value="Global">Global</option>
    <option value="California Coast">California Coast</option>
    <option value="US West Coast">US West Coast</option>
    <option value="Western Hemisphere">Western Hemisphere</option>
    <option value="North Pacific">North Pacific</option>
    <option value="Pacific Ocean">Pacific Ocean</option>
  </select>
</div>

<!-- Step 4 -->
<div id="step-timeseries" class="mb-3" style="display: none;">
  <label><strong>**Step 4:** Time Series Type</strong></label>
  <select id="timeSeriesFilter" class="form-select">
    <option value="">-- Select --</option>
    <option value="All">All</option>
    <option value="Long Time Series">Long Time Series</option>
    <option value="Short Time Series">Short Time Series</option>
  </select>
</div>

<!-- Step 5 -->
<div id="step-geo" class="mb-3" style="display: none;">
  <label><strong>**Step 5:** Is it Geostationary?</strong></label>
  <select id="geoFilter" class="form-select">
    <option value="">-- Select --</option>
    <option value="All">All</option>
    <option value="Yes">Yes</option>
    <option value="No">No</option>
  </select>
</div>

<!-- Step 6 -->
<div id="step-blend" class="mb-3" style="display: none;">
  <label><strong>**Step 6:** Is it a Blended Product?</strong></label>
  <select id="blendFilter" class="form-select">
    <option value="">-- Select --</option>
    <option value="All">All</option>
    <option value="Yes">Yes</option>
    <option value="No">No</option>
  </select>
